    /**
     * Run the database seeds.
     */

    public function run(): void
    {
        if (empty($this->repurchase_accounts)) {
            $this->command->error('No Repurchase Account data provided in the array.');
            return;
        }

        \DB::statement('SET FOREIGN_KEY_CHECKS=0;');
  
        $this->command->info('Starting Repurchase Account migration from array...');
        $this->command->getOutput()->progressStart(count($this->repurchase_accounts));

        foreach ($this->repurchase_accounts as $acc) {
            try {
                \DB::beginTransaction();

                $this->command->info('Processing Repurchase Account id : '.$acc['id']);

                // Create new User
                $tdsscc = new RepurchaseAccount();
                $tdsscc->id = $acc['id'];
                $tdsscc->user_id = $acc['user_id'];
                $tdsscc->amount = $acc['amount'];
                $tdsscc->which_for = $acc['which_for'];
                $tdsscc->status = $acc['status'];
                $tdsscc->created_at = $acc['created_at'];
                $tdsscc->updated_at = $acc['updated_at'];
                $tdsscc->save();

                \DB::commit();
                $this->command->getOutput()->progressAdvance();
            } catch (\Exception $e) {
                \DB::rollBack();
                $this->command->error("Failed to migrate Repurchase Account" . $e->getMessage());  
            }
        }

        \DB::statement('SET FOREIGN_KEY_CHECKS=1;');

        $this->command->getOutput()->progressFinish();
        $this->command->info('Repurchase Account migration from array completed.');
    }
}
